// A typed config struct is the target for whatever loader you use.
type Config struct {
	Port     int    `mapstructure:"port"`
	DBURL    string `mapstructure:"db_url"`
	LogLevel string `mapstructure:"log_level"`
}

func main() {
	// 12-factor: never hardcode; read from the environment at startup.
	cfg := Config{
		Port:     8080,                    // default
		DBURL:    os.Getenv("APP_DB_URL"), // from env
		LogLevel: os.Getenv("APP_LOG_LEVEL"),
	}
	fmt.Printf("%+v\n", cfg)
	// Output (example): {Port:8080 DBURL:postgres://... LogLevel:info}
}

// Merge a file, defaults, and env vars into one Viper view.
func load() *viper.Viper {
	v := viper.New()
	v.SetConfigName("config") // config.yaml
	v.SetConfigType("yaml")
	v.AddConfigPath(".")
	v.SetDefault("port", 8080) // used if nothing else sets it

	v.SetEnvPrefix("APP")          // APP_PORT, APP_DB_URL ...
	v.AutomaticEnv()               // read matching env vars

	if err := v.ReadInConfig(); err != nil {
		// missing file is often OK if env/defaults suffice
		if _, ok := err.(viper.ConfigFileNotFoundError); !ok {
			log.Fatalf("read config: %v", err)
		}
	}
	return v
}

// Demonstrate precedence: env beats the file, Set beats everything.
func main() {
	v := viper.New()
	v.SetDefault("port", 8080)     // lowest priority
	v.Set("config_file_port", 9090) // pretend this came from a file

	os.Setenv("APP_PORT", "7070")
	v.SetEnvPrefix("APP")
	v.AutomaticEnv() // env var now visible

	fmt.Println(v.GetInt("port")) // 7070: env overrides the 8080 default

	v.Set("port", 6060)           // explicit Set has the highest priority
	fmt.Println(v.GetInt("port")) // 6060: beats env, file, and default
	// Output:
	// 7070
	// 6060
}

type Config struct {
	Port  int    `mapstructure:"port"`
	DBURL string `mapstructure:"db_url"`
}

func loadAndWatch(v *viper.Viper) (*Config, error) {
	var cfg Config
	if err := v.Unmarshal(&cfg); err != nil { // merged view -> struct
		return nil, fmt.Errorf("unmarshal config: %w", err)
	}

	v.WatchConfig() // watch the file for edits
	v.OnConfigChange(func(e fsnotify.Event) {
		log.Printf("config changed: %s", e.Name)
		_ = v.Unmarshal(&cfg) // re-decode on change
	})
	return &cfg, nil
}

type Signup struct {
	Email string   `validate:"required,email"`
	Age   int      `validate:"gte=18,lte=120"`
	Tags  []string `validate:"required,dive,min=2"` // dive: each tag min len 2
}

func main() {
	v := validator.New()
	s := Signup{Email: "nope", Age: 15, Tags: []string{"a"}}
	if err := v.Struct(s); err != nil {
		for _, fe := range err.(validator.ValidationErrors) {
			fmt.Printf("%s failed on %q\n", fe.Field(), fe.Tag())
		}
	}
	// Output:
	// Email failed on "email"
	// Age failed on "gte"
	// Tags[0] failed on "min"
}

// A custom rule: value must be a lowercase slug.
var slugRE = regexp.MustCompile(`^[a-z0-9-]+$`)

func isSlug(fl validator.FieldLevel) bool {
	return slugRE.MatchString(fl.Field().String())
}

func main() {
	v := validator.New()
	_ = v.RegisterValidation("slug", isSlug) // tag "slug" -> isSlug

	type Tenant struct {
		Name string `validate:"required,slug"`
	}
	err := v.Struct(Tenant{Name: "Bad Name!"})
	fmt.Println(err != nil) // true: fails the custom slug rule
	// Gin: binding.Validator.Engine().(*validator.Validate).RegisterValidation("slug", isSlug)
	// Output: true
}

