package main

import (
	"fmt"
	"os"

	"github.com/spf13/viper"
)

type Config struct {
	Port  int    `mapstructure:"port"`
	DBURL string `mapstructure:"db_url"`
}

func main() {
	v := viper.New()
	v.SetDefault("port", 8080)         // lowest priority
	v.Set("db_url", "postgres://file") // pretend loaded from a file

	// Enable env reading with a prefix: APP_PORT, APP_DB_URL.
	os.Setenv("APP_PORT", "7070")
	v.SetEnvPrefix("APP")
	v.AutomaticEnv() // without this, APP_PORT is ignored!

	var cfg Config
	if err := v.Unmarshal(&cfg); err != nil {
		panic(err)
	}
	fmt.Printf("port=%d db=%s\n", cfg.Port, cfg.DBURL)
}

package main

import (
	"fmt"

	"github.com/go-playground/validator/v10"
)

type CreateUser struct {
	Email string   `validate:"required,email"`
	Age   int      `validate:"gte=18,lte=120"`
	Roles []string `validate:"required,dive,oneof=admin editor viewer"`
}

func main() {
	validate := validator.New() // reuse across the app

	u := CreateUser{Email: "bad", Age: 12, Roles: []string{"admin", "ghost"}}
	err := validate.Struct(u)
	if err != nil {
		for _, fe := range err.(validator.ValidationErrors) {
			fmt.Printf("%s: failed %q\n", fe.Namespace(), fe.Tag())
		}
	}
}

package main

import (
	"net/http"
	"regexp"

	"github.com/gin-gonic/gin"
	"github.com/gin-gonic/gin/binding"
	"github.com/go-playground/validator/v10"
)

var slugRE = regexp.MustCompile(`^[a-z0-9-]+$`)

func isSlug(fl validator.FieldLevel) bool {
	return slugRE.MatchString(fl.Field().String())
}

type CreateTenant struct {
	Slug string `json:"slug" binding:"required,slug"`
}

func main() {
	// Register the custom rule on Gin's shared validator engine.
	if v, ok := binding.Validator.Engine().(*validator.Validate); ok {
		_ = v.RegisterValidation("slug", isSlug)
	}

	r := gin.New()
	r.POST("/tenants", func(c *gin.Context) {
		var in CreateTenant
		if err := c.ShouldBindJSON(&in); err != nil { // runs validator
			c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
			return
		}
		c.JSON(http.StatusOK, gin.H{"slug": in.Slug})
	})
	_ = r.Run(":8080")
}

