package solution

import (
	"testing"

	"github.com/spf13/viper"
)

func TestLoadDefaultsAndValidates(t *testing.T) {
	v := viper.New()
	v.Set("db_url", "postgres://localhost") // required field present
	cfg, err := Load(v)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if cfg.Port != 8080 {
		t.Fatalf("port = %d, want default 8080", cfg.Port)
	}
}

func TestLoadFailsOnMissingDBURL(t *testing.T) {
	v := viper.New()
	if _, err := Load(v); err == nil {
		t.Fatalf("expected validation error for missing db_url")
	}
}

func TestEnvOverride(t *testing.T) {
	t.Setenv("APP_PORT", "9090")
	v := viper.New()
	v.Set("db_url", "postgres://localhost")
	cfg, err := Load(v)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if cfg.Port != 9090 {
		t.Fatalf("port = %d, want env override 9090", cfg.Port)
	}
}

