func Load() int {
	v := viper.New()
	v.SetDefault("port", 8080)
	v.SetEnvPrefix("APP")
	v.AutomaticEnv() // FIX: now APP_PORT is read on demand
	// For nested keys (db.url -> APP_DB_URL) also:
	// v.SetEnvKeyReplacer(strings.NewReplacer(".", "_"))
	return v.GetInt("port") // 9090 when APP_PORT=9090 is set
}

func FieldErrors(err error) map[string]string {
	ve, ok := err.(validator.ValidationErrors)
	if !ok {
		return nil // nil error or a non-validation error
	}
	out := make(map[string]string, len(ve))
	for _, fe := range ve {
		msg := "failed " + fe.Tag()
		if p := fe.Param(); p != "" {
			msg += "=" + p // e.g. failed min=2
		}
		out[fe.Field()] = msg
	}
	return out
}

func MustGetInt(v *viper.Viper, key string) (int, error) {
	if !v.IsSet(key) { // true if any source (default/file/env/Set) has it
		return 0, fmt.Errorf("required config key %q is not set", key)
	}
	return v.GetInt(key), nil
}
